5	const { execFileSync, execSync } = require("child_process");
6	const path = require("path");
7	const fs = require("fs");
8	
9	const PACKAGE = require("./package.json");
10	const EXPECTED_VER = PACKAGE.version; // e.g. "1.1.0-beta.4"
11	const NAME = "cc-connect";
12	const binDir = path.join(__dirname, "bin");
13	const ext = process.platform === "win32" ? ".exe" : "";
14	const binaryPath = path.join(binDir, NAME + ext);
15	
16	// parseVersion splits "1.2.3-beta.1" into { nums: [1,2,3], preTag: "beta", preNum: 1 }
17	function parseVersion(v) {
18	  v = v.replace(/^v/, "").trim();
19	  const [base, ...rest] = v.split("-");
20	  const nums = base.split(".").map(Number);
21	  const pre = rest.join("-");
22	  const m = pre.match(/^([a-zA-Z]+)\.?(\d+)?$/);
23	  return { nums, preTag: m ? m[1] : pre, preNum: m && m[2] ? parseInt(m[2], 10) : 0, hasPre: pre !== "" };
24	}
25	
26	// isNewerOrEqual returns true if installed >= expected
27	function isNewerOrEqual(installed, expected) {
28	  const a = parseVersion(installed);
29	  const b = parseVersion(expected);
30	  const len = Math.max(a.nums.length, b.nums.length);
31	  for (let i = 0; i < len; i++) {
32	    const av = a.nums[i] || 0;
33	    const bv = b.nums[i] || 0;
34	    if (av > bv) return true;
35	    if (av < bv) return false;
36	  }
37	  // Same base: no pre-release >= any pre-release (1.2.3 >= 1.2.3-beta.1)
38	  if (!a.hasPre && b.hasPre) return true;
39	  if (a.hasPre && !b.hasPre) return false;
40	  if (!a.hasPre && !b.hasPre) return true;
41	  // Both pre-release: compare tag then number (rc > beta, beta.10 > beta.9)
42	  if (a.preTag !== b.preTag) return a.preTag > b.preTag;
43	  return a.preNum >= b.preNum;
44	}
45	
46	function needsReinstall() {
47	  if (!fs.existsSync(binaryPath)) return true;
48	  try {
49	    const out = execFileSync(binaryPath, ["--version"], { encoding: "utf8", timeout: 5000 });
50	    if (out.includes(EXPECTED_VER)) return false;
51	    // Extract version from output (e.g. "cc-connect 1.2.2-beta.1" or "1.2.2-beta.1")
52	    const match = out.match(/(\d+\.\d+\.\d+[^\s]*)/);
53	    if (match && isNewerOrEqual(match[1], EXPECTED_VER)) return false;
54	    return true;
55	  } catch {
56	    return true;
57	  }
58	}
59	
60	if (needsReinstall()) {
61	  console.log(`[cc-connect] Binary missing or outdated, installing v${EXPECTED_VER}...`);
